_TRANSLIT = {
    'õ': 'o',
    'ö': 'o',
    'ü': 'u',
    'ä': 'a',
    'š': 's',
    'ž': 'z',
}


def slugify(s):
    out = []
    for ch in s.lower():
        ch = _TRANSLIT.get(ch, ch)
        if ch.isalnum():
            out.append(ch)
        elif out and out[-1] != '-':
            out.append('-')
    return ''.join(out).rstrip('-')

import re
import unicodedata


def slugify(s):
    s = s.lower()
    # Decompose accented characters and drop combining marks,
    # so e.g. 'õ' becomes 'o'.
    s = unicodedata.normalize('NFKD', s)
    s = ''.join(ch for ch in s if not unicodedata.combining(ch))
    out = []
    for ch in s:
        if ch.isalnum() and ord(ch) < 128:
            out.append(ch)
        else:
            out.append('-')
    # Collapse consecutive separators and strip leading/trailing ones.
    return re.sub(r'-+', '-', ''.join(out)).strip('-')

