import unicodedata


def slugify(s):
    s = unicodedata.normalize('NFKD', s).lower()
    s = s.encode('ascii', 'ignore').decode('ascii')
    out = []
    for ch in s:
        if ch.isalnum():
            out.append(ch)
        elif not out or out[-1] != '-':
            out.append('-')
    return ''.join(out).strip('-')

