def slug_unique(names):
    counts = {}
    taken = set()
    result = []
    for name in names:
        slug = slugify(name)
        if slug in taken:
            counts[slug] = counts.get(slug, 1) + 1
            candidate = f'{slug}-{counts[slug]}'
            while candidate in taken:
                counts[slug] += 1
                candidate = f'{slug}-{counts[slug]}'
            slug = candidate
        else:
            counts[slug] = 1
        taken.add(slug)
        result.append(slug)
    return result
